step.script:
env HOME=/tmp bash -lc 'set -eu; CITY_SLUG="$(printf "%s" "Almeria" | tr "[:upper:]" "[:lower:]")"; SRC_DIR=""; for d in /home/ubuntu/data_storage/*; do
  [ -d "$d" ] || continue;
  if [ "$(basename "$d" | tr "[:upper:]" "[:lower:]")" = "$CITY_SLUG" ]; then
    SRC_DIR="$d";
    break;
  fi;
done; if [ -z "$SRC_DIR" ]; then
  echo "City data folder not found in /home/ubuntu/data_storage for Almeria";
  exit 1;
fi; SRC_FILE="$SRC_DIR/00_master/master_events.json"; DEST_FILE="/home/ubuntu/work/frontend_build/test_frontend/data/$CITY_SLUG/master_events.json"; [ -f "$SRC_FILE" ] || { echo "Missing source file: $SRC_FILE"; exit 1; }; mkdir -p "$(dirname "$DEST_FILE")"; cp "$SRC_FILE" "$DEST_FILE"; echo "Snapshot copied to $DEST_FILE"'

env HOME=/tmp bash -lc 'set -eu; CITY_SLUG="$(printf "%s" "$TARGET_CITY" | tr "[:upper:]" "[:lower:]")"; SNAPSHOT_PATH="data/$CITY_SLUG/master_events.json"; docker run --rm -v /home/ubuntu/work/frontend_build/test_frontend:/repo -v /home/ubuntu/.ssh:/root/.ssh:ro -w /repo alpine/git:latest sh -lc " set -eu; git add \"$SNAPSHOT_PATH\"; if git diff --cached --quiet -- \"$SNAPSHOT_PATH\"; then
  echo \"No snapshot changes to commit for $SNAPSHOT_PATH\";
  exit 0;
fi; BRANCH=\$(git rev-parse --abbrev-ref HEAD); COMMIT_MSG=\"chore(snapshot): update master_events for $CITY_SLUG \$(date -u +%Y-%m-%dT%H:%M:%SZ)\"; git -c user.name=\"Dagu Snapshot Bot\" -c user.email=\"dagu-snapshot@example.com\" commit -m \"\$COMMIT_MSG\" -- \"$SNAPSHOT_PATH\"; git push origin \"\$BRANCH\" "'

env HOME=/tmp bash -lc 'set -eu; IMAGE="infra_scripts-test_frontend_build:latest"; if ! docker image inspect "$IMAGE" >/dev/null 2>&1; then
  echo "Missing image: $IMAGE";
  echo "Build it first with: docker compose --profile build build test_frontend_build";
  exit 1;
fi; EXTRA_ARGS=""; if [ "${NO_DOWNLOAD_IMAGES}" = "1" ]; then
  EXTRA_ARGS="--no-download-images";
fi; docker run --rm -e ORBITA_CITY="$TARGET_CITY" -v /home/ubuntu/work/frontend_build/test_frontend:/app -v infra_scripts_test_frontend_node_modules:/app/node_modules -v /home/ubuntu/work/frontend_build/test_frontend/dist:/app/dist -v /home/ubuntu/data_storage:/home/ubuntu/data_storage "$IMAGE" --city "$TARGET_CITY" --out "$OUT_DIR" --base-url "$BASE_URL" $EXTRA_ARGS'
